import React, { useState, useEffect } from 'react';
import { useNavigate, Link, useLocation } from 'react-router-dom';
import { supabaseService } from '../../services/supabaseService';
import { supabase } from '../../utils/supabaseClient';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import Icon from '../../components/AppIcon';
import { useToast } from '../../contexts/ToastContext';

const ForgotPassword = () => {
    const [step, setStep] = useState(1); // 1: Request, 2: Sent, 3: Reset
    const [email, setEmail] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const navigate = useNavigate();
    const location = useLocation();
    const { addToast } = useToast();

    // Handle recovery link detection
    useEffect(() => {
        // Supabase sends a recovery link that sets a session. 
        // We listen for the event 'PASSWORD_RECOVERY'
        const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
            if (event === 'PASSWORD_RECOVERY') {
                setStep(3);
                addToast('Identity verified securely! Please set your new password.', 'success');
            }
        });

        // Fallback: Check if we are already in a recovery session or have tokens in the URL
        const checkSession = async () => {
            const { data: { session } } = await supabase.auth.getSession();
            // If the URL contains an access token and we're on this page, 
            // the onAuthStateChange above should catch it, but this is a backup.
            if (window.location.hash.includes('type=recovery')) {
                setStep(3);
            }
        };
        checkSession();

        return () => subscription.unsubscribe();
    }, [addToast]);

    const handleRequestReset = async (e) => {
        e.preventDefault();
        if (!email) {
            addToast('Please enter your email address', 'error');
            return;
        }
        setIsLoading(true);
        setError('');
        try {
            await supabaseService.sendResetPasswordEmail(email);
            // Always set success step even if email doesn't exist (prevents enumeration)
            setStep(2);
            addToast('Identity verification initiated. Please check your inbox.', 'success');
        } catch (err) {
            // Even on error, we might want to show success to prevent enumeration, 
            // but for real system errors (like rate limits) we should still log it.
            console.error('Reset error:', err);
            setStep(2); // Still move to step 2 to stay generic
            addToast('Identity verification initiated. Please check your inbox.', 'success');
        } finally {
            setIsLoading(false);
        }
    };

    const handleUpdatePassword = async (e) => {
        e.preventDefault();
        setError('');

        if (newPassword !== confirmPassword) {
            addToast('Passwords do not match', 'error');
            return;
        }
        if (newPassword.length < 6) {
            addToast('Password must be at least 6 characters', 'error');
            return;
        }

        setIsLoading(true);
        try {
            await supabaseService.updatePassword(newPassword);
            addToast('Password updated successfully! You can now sign in.', 'success');

            // Sign out to clear the recovery session and force fresh login
            await supabaseService.logout();
            navigate('/login');
        } catch (err) {
            setError(err.message || 'Failed to reset password. The link may have expired.');
            addToast('Reset failed', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-slate-50 dark:bg-gray-900 flex items-center justify-center p-4">
            <div className="w-full max-w-md">
                <div className="text-center mb-8">
                    <Link to="/login" className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-primary transition-colors mb-6">
                        <Icon name="ArrowLeft" size={16} />
                        Back to Login
                    </Link>
                    <div className="w-20 h-20 bg-primary/10 rounded-3xl flex items-center justify-center text-primary mx-auto mb-4 shadow-sm border border-primary/10">
                        <Icon name={step === 3 ? "Lock" : "ShieldCheck"} size={40} />
                    </div>
                    <h1 className="text-3xl font-bold text-primary">Account Security</h1>
                    <p className="text-muted-foreground mt-2 px-6">
                        {step === 1 ? 'Enter your email for a secure password reset link.' :
                            step === 2 ? 'Check your inbox for the verification link.' :
                                'Verified. Create your secure new password.'}
                    </p>
                </div>

                <div className="bg-card border border-border rounded-[2rem] shadow-xl p-8 md:p-10 relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-primary via-secondary to-accent opacity-50" />

                    {error && (
                        <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/10 border border-red-200 dark:border-red-900/20 rounded-2xl flex items-center gap-3 text-red-600 dark:text-red-400 text-sm animate-in fade-in slide-in-from-top-2">
                            <Icon name="AlertCircle" size={18} />
                            <span>{error}</span>
                        </div>
                    )}

                    {step === 1 && (
                        <form onSubmit={handleRequestReset} className="space-y-6">
                            <div>
                                <label className="block text-sm font-bold text-primary mb-2">Registered Email</label>
                                <Input
                                    type="email"
                                    placeholder="your@email.com"
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    required
                                    className="h-12 text-lg"
                                />
                            </div>
                            <Button type="submit" fullWidth size="xl" loading={isLoading}>
                                Send Reset Link
                            </Button>
                        </form>
                    )}

                    {step === 2 && (
                        <div className="text-center space-y-6 animate-in fade-in slide-in-from-bottom-4">
                            <div className="p-6 bg-blue-50 dark:bg-blue-900/10 border border-blue-100 dark:border-blue-900/20 rounded-3xl">
                                <Icon name="Mail" size={48} className="mx-auto text-blue-600 dark:text-blue-400 mb-4" />
                                <h3 className="font-bold text-blue-900 dark:text-blue-300">Verification Link Sent</h3>
                                <p className="text-sm text-blue-700/70 dark:text-blue-400/70 mt-2">
                                    We've sent a secure reset link to your email. Please click it within 1 hour to verify your identity.
                                </p>
                            </div>
                            <Button variant="outline" fullWidth onClick={() => setStep(1)}>
                                Didn't get it? Try again
                            </Button>
                        </div>
                    )}

                    {step === 3 && (
                        <form onSubmit={handleUpdatePassword} className="space-y-6 animate-in fade-in zoom-in-95">
                            <div className="p-4 bg-green-50 dark:bg-green-900/10 border border-green-100 dark:border-green-900/20 rounded-2xl mb-6 flex items-center gap-3">
                                <div className="w-8 h-8 rounded-full bg-green-500 text-white flex items-center justify-center shrink-0 shadow-sm">
                                    <Icon name="Check" size={16} />
                                </div>
                                <p className="text-xs text-green-700 dark:text-green-400 font-medium">
                                    System Verification successful! Choose a strong password.
                                </p>
                            </div>
                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-bold text-primary mb-2">New Password</label>
                                    <Input
                                        type="password"
                                        placeholder="Min. 6 characters"
                                        value={newPassword}
                                        onChange={(e) => setNewPassword(e.target.value)}
                                        required
                                        className="h-12"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-primary mb-2">Confirm New Password</label>
                                    <Input
                                        type="password"
                                        placeholder="Repeat new password"
                                        value={confirmPassword}
                                        onChange={(e) => setConfirmPassword(e.target.value)}
                                        required
                                        className="h-12"
                                    />
                                </div>
                            </div>
                            <Button type="submit" fullWidth size="xl" loading={isLoading} variant="success">
                                Update Password
                            </Button>
                        </form>
                    )}
                </div>

                <div className="mt-8 text-center text-sm text-muted-foreground">
                    <p>Issues verifying? <Link to="/contact" className="text-primary font-bold hover:underline">Support Hub</Link></p>
                </div>
            </div>
        </div>
    );
};

export default ForgotPassword;
